    assert n > 2

    for t in seq(0, tsteps):
        # First sweep: read from A, write into B.
        for i in seq(1, n - 1):
            B[i] = 0.33333 * (A[i - 1] + A[i] + A[i + 1])

        # Second sweep: read from B, write back into A.
        for i in seq(1, n - 1):
            A[i] = 0.33333 * (B[i - 1] + B[i] + B[i + 1])


