#   ii_B = i_vec_B * I_UNROLL + iv_B
kernel_jacobi_1d_sched = divide_loop(
    kernel_jacobi_1d_sched,
    kernel_jacobi_1d_sched.find_loop("ii_B"),
    I_UNROLL,
    ("i_vec_B", "iv_B"),
    tail="guard",
)

